GimCorpus.put(490,0,[[1,1,"מצות עשה מן התורה לזעוק ולהריע בחצוצרות וכו'. (א\"ה כתב ה\"ה וראיתי לרבינו וכו' ועיין בדברי הרב המחבר בספר דרשותיו בדרך מצותיך ח\"א (דף ס'):",1,0],[1,9,"ולא יתענה בשבתות ולא במועדות ולא בר\"ח ולא בחנוכה ופורים. (א\"ה עיין בפ\"ו מהלכות כלי מקדש דין ט' כי שם צידד הרב המחבר לומר דאסור להתענות בע\"פ מחצות ולמעלה יע\"ש):",1,0]]);
